# Read and process the CO data for 2000
with open('daily_42101_2000.csv', 'r') as f:
    reader = csv.DictReader(f)

    # Dictionary to store daily max CO values by area
    areas = {
        "Portland-Vancouver-Hillsboro, OR-WA": {},
        "Wichita, KS": {},
        "San Diego-Carlsbad, CA": {}
    }

