    exceed_days = [d for d, v in daily_values.items() if v > 4.4]
    print(f"\n{area_name}:")
    print(f"  Total days with data: {len(daily_values)}")
    print(f"  Days > 4.4 ppm: {len(exceed_days)}")
    if exceed_days:
        print(f"  Max CO value: {max(daily_values.values()):.2f} ppm")
    else:
        print(f"  Max CO value: {max(daily_values.values()):.2f} ppm")

