            with zipfile.ZipFile(f"daily_42101_{year}.zip", 'r') as zip_ref:
                zip_ref.extractall()
            os.remove(f"daily_42101_{year}.zip")
        except Exception as e:
            print(f"Error downloading {year}: {e}")
            continue

    # Process the file
