        "Portland-Vancouver-Hillsboro, OR-WA": {},
        "Wichita, KS": {},
        "San Diego-Carlsbad, CA": {}
    }

    try:
        with open(filename, 'r', encoding='utf-8', errors='ignore') as f:
            reader = csv.DictReader(f)
            for row in reader:
                cbsa = row.get('CBSA Name', '')
                if cbsa in areas:
