    all_good = True
    for area_name, daily_values in areas.items():
        exceed_days = [d for d, v in daily_values.items() if v > 4.4]
        max_val = max(daily_values.values()) if daily_values else 0
        year_result[area_name] = {
            'days_with_data': len(daily_values),
            'exceed_days': len(exceed_days),
            'max_val': max_val
