        if exceed_days:
            all_good = False

    results[year] = {
        'all_good': all_good,
        'areas': year_result
    }

    status = "✓ ALL GOOD" if all_good else "✗ NOT ALL GOOD"
    print(f"{year}: {status}")
    for area, data in year_result.items():
        print(f"  {area}: {data['exceed_days']} days > 4.4ppm, max={data['max_val']:.2f}ppm")

print("\n\n=== SUMMARY ===")
good_years = [y for y, r in results.items() if r['all_good']]
print(f"Years where ALL THREE areas had CO <= 4.4 ppm every day: {good_years}")

