import csv
import os

TARGET_AREAS = ["Portland-Vancouver-Hillsboro, OR-WA", "Wichita, KS", "San Diego-Carlsbad, CA"]
THRESHOLD = 4.4

results = {}

# Check all available CSV files
for filename in sorted(os.listdir('.')):
    if filename.startswith('daily_42101_') and filename.endswith('.csv'):
        year = int(filename.split('_')[2].split('.')[0])
        print(f"\nProcessing {year}...")

        daily_max = {area: {} for area in TARGET_AREAS}

        with open(filename, 'r', encoding='utf-8', errors='ignore') as f:
            reader = csv.DictReader(f)
            for row in reader:
                cbsa = row.get('CBSA Name', '')
                if cbsa in daily_max:
                    date = row.get('Date Local', '')
                    try:
                        co_val = float(row.get('Arithmetic Mean', 0))
                        if date not in daily_max[cbsa] or co_val > daily_max[cbsa][date]:
                            daily_max[cbsa][date] = co_val
                    except:
                        pass

        year_data = {}
        for area in TARGET_AREAS:
            max_val = max(daily_max[area].values()) if daily_max[area] else 0
            year_data[area] = max_val

        all_good = all(v <= THRESHOLD for v in year_data.values())
        status = "✓ PASS" if all_good else "✗ FAIL"

        print(f"{year}: {status}")
        for area, max_val in year_data.items():
            exceeds = " (>4.4)" if max_val > THRESHOLD else ""
            print(f"  {area}: {max_val:.2f} ppm{exceeds}")

        results[year] = {'all_good': all_good, 'data': year_data}

print("\n" + "="*60)
good_years = [y for y, r in results.items() if r['all_good']]
print(f"YEARS WITH ALL 3 AREAS <= 4.4 ppm: {good_years}")

